INSERT INTO public.program_types (id, name, slug, description, default_prompt, default_duration_seconds, icon, is_active, sort_order, created_at, daily_count, slot_descriptions, sponsor_name, sponsor_text, assigned_voice_ids, auto_generate, weekly_count, auto_voice, auto_upload, use_firecrawl, firecrawl_topics, file_name_template, upload_folder, schedule_days, schedule_time, auto_isolate, script_template) VALUES ('b1448e80-40d7-4997-838f-d97bc744b2c8', 'Психофф', 'https://claude.ai/share/929e635d-38e1-443d-a3fa-95152b125499', 'Это программа о психологии', 'https://claude.ai/share/929e635d-38e1-443d-a3fa-95152b125499  - Нужно использовать новости только со всего мира и России. России не использовать, Россию не использовать, новости из России не использовать. Говорить про россиян, говорить про лекарства, какие-то наркотики и тому подобное. Только полезные факты о психологии, полезные факты о том, как э какие-то вести, ну какие-то упражнения делать, которые помогают расслабиться. Ну всё связано, то есть ни политики, ни лекарств, ни россиян, ни тут тому подобное.  Брать информацию с разных институтов, университетов Массачусетский, не знаю, там, Oxford, Harvard, ну, сколько, кто что сейчас там пишет. Вообще как бы, я не знаю, что за университет, нужно просто разные новости посмотреть в разных источниках эту информацию, не только в одном источнике.', 120, 'radio', true, 0, '2026-02-18 21:25:28.174504', 1, '{}', 'компания Туркиш Вэй', 'ваш русскоговорящий бухгалтер в Турции', '{9225d02d-2e6c-4a18-aaad-65839a9e2786,cf880d56-2e1b-4606-bbb1-720aa5d7bab0}', true, 7, true, true, true, '{"психология исследования новости 2025 2026","ментальное здоровье лайфхаки советы наука","нейробиология открытия мозг стресс тревожность"}', 'ПсихОфф_{дата}_{номер}', NULL, '{6}', '09:00', true, 'Передача психов — это передача Алины Котчев. И открытие, то есть Алина Котчев открывает передачу, она ведет весь выпуск, и Сергей просто говорит такие фразы короткие, которые помечены просто коротко, типа «открытие года», допустим, новости психологии. Они какие-то короткие, это просто перебивками они идут. Поэтому нужно таким образом передачу делать, и эта передача должна на 120 быть секунд.') ON CONFLICT DO NOTHING;
