INSERT INTO public.settings (id, eleven_labs_api_key, yandex_disk_token, male_voice_id, female_voice_id, daily_dialogs_count, default_prompt, anthropic_api_key, ai_provider, station_name, station_logo, station_description, station_website, station_attachments, station_location, daily_prompt, slot_prompts, accumulated_learnings, freesound_api_key, user_id, global_firecrawl_topics, dialog_style, dialog_replicas) VALUES ('3e9150f6-67dd-48bd-a8a4-e5ea02b8a2e5', 'e2bdaf6c333b1ecf585cb65392f34ea32a17e973f691fea44951aa231b6b4fd5', '', 'onwK4e9ZLuTAKqWW03F9', 'EXAVITQu4vr4xnSDxMaL', 12, 'Радиостанция RuWave 94FM Alanya объединяет всех русскоязычных разных национальностей, которые знают русский язык. Поэтому мы не должны акцентироваться на новости из России и как бы да, если шоу-бизнес, мы говорим о каких-то звездах, которых знают русскоязычные, но не акцентировать на это как бы большой момент. Дальше не ставить новости о каких-то звездах, которые слишком политизированы, потому что у нас нет политики. У нас вообще не должно на радиостанции быть никакой политики. Не должны ни за правых, ни за левых, ни Украину ни за РФ, ни за Путина, ни за Трампа, никого. Мы просто развлекательная часть. То есть всяких там типа шаманов и там подобное. Или там, допустим, мы говорим о том, что там Газманов что-то там сказал за Россию, за патриотизм. Этого не должно быть вообще. Соответственно, политики нет, криминала нет, никаких там желтой прессы, ничего. Стараться информацию брать о новостях, использовать в каких-то передачах из мировых источников, из российских, из турецких, переводить и, соответственно, добавлять в наши передачи. То есть это должно быть по умолчанию.', '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', 'anthropic', 'РуВэйв 94ФМ Аланья', '/uploads/1766608239570-nro3tg.png', 'Добро пожаловать на волну радости и отличного настроения – добро пожаловать на радиостанцию "RuWave 94FM"! Мы - первая русскоязычная радиостанция, расположенная на живописном анталийском побережье Турции, в самом сердце курортного города Аланья. Наши волшебные волны звучат на частоте 94FM, чтобы привнести яркость и радость в каждый момент вашего пребывания.  
